package controller;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;import service.TheoDoiChuyenService;
/** GET /api/trip-monitor và /{id}; POST /{id}/complete chỉ khi mọi điểm đã giao hoặc đã xử lý trả kho. Phụ thuộc migration S6-06. */
@WebServlet("/api/trip-monitor/*") public class TheoDoiChuyenServlet extends NghiepVuKhoServlet{private final TheoDoiChuyenService s=new TheoDoiChuyenService();protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try{String p=path(q);send(r,p.equals("/")?s.list(user(q),roles(q)):s.detail(id(p.substring(1)),user(q),roles(q)));}catch(Exception e){fail(r,e);}}protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{try{String p=path(q);if(!p.matches("/\\d+/complete"))throw new NoSuchElementException("Không tìm thấy chức năng");s.complete(id(p.split("/")[1]),user(q),roles(q));send(r,Map.of("message","Đã kết thúc chuyến"));}catch(Exception e){fail(r,e);}}}
